import { act, fireEvent, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

import { makeResponse } from "@/test/fixtures";

import { AnswerView } from "./AnswerView";

function renderView() {
  render(<AnswerView question="Who?" scopeLabel="All documents" response={makeResponse()} />);
}

function card(id: number) {
  const element = document.getElementById(`src-${id}`);
  if (!element) throw new Error(`No source card ${id}`);
  return element;
}

describe("AnswerView", () => {
  afterEach(() => {
    vi.useRealTimers();
  });

  it("scrolls to, focuses and highlights the cited source", () => {
    renderView();

    fireEvent.click(screen.getByRole("link", { name: "Source 2" }));

    expect(card(2).scrollIntoView).toHaveBeenCalled();
    expect(document.activeElement).toBe(card(2));
    expect(card(2).dataset.highlighted).toBe("true");
    expect(card(1).dataset.highlighted).toBe("false");
  });

  it("removes the highlight after a moment", () => {
    vi.useFakeTimers();
    renderView();
    fireEvent.click(screen.getByRole("link", { name: "Source 1" }));

    act(() => {
      vi.advanceTimersByTime(2000);
    });

    expect(card(1).dataset.highlighted).toBe("false");
  });

  it("lists retrieved passages that were not cited", () => {
    renderView();

    expect(screen.getByText("1 more passage retrieved but not cited")).toBeTruthy();
    expect(screen.getByText("2 cited of 3 retrieved")).toBeTruthy();
  });

  it("toggles the retrieval scores", () => {
    renderView();
    expect(screen.queryByText(/rrf 0\.0323/)).toBeNull();

    fireEvent.click(screen.getByRole("button", { name: "Show retrieval details" }));

    expect(screen.getAllByText(/rrf 0\.0323/)).toHaveLength(3);
  });
});
