import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { fireEvent, render, screen, waitFor } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";

import type { LibraryDocument } from "@/api/types";
import { DOCUMENT, makePassage, makeResponse } from "@/test/fixtures";

import App from "./App";

type Reply = { status?: number; body: unknown };

interface Routes {
  ask?: Reply | Reply[];
  documents?: LibraryDocument[];
  upload?: Reply;
  job?: Reply;
}

function stubApi(routes: Routes = {}) {
  const askReplies = [routes.ask ?? { body: makeResponse() }].flat();
  const documentLists = [routes.documents ?? [DOCUMENT]];
  const calls: { path: string; init?: RequestInit }[] = [];

  const reply = ({ status = 200, body }: Reply) =>
    Promise.resolve(new Response(JSON.stringify(body), { status }));

  vi.stubGlobal("fetch", (path: string, init?: RequestInit) => {
    calls.push({ path, init });
    if (path === "/api/health") return reply({ body: { llm_provider: "fake" } });
    if (path === "/api/ask") return reply(askReplies.shift() ?? { body: makeResponse() });
    if (path === "/api/documents" && init?.method === "POST") {
      return reply(routes.upload ?? { status: 202, body: { job_id: "job", doc_id: "new" } });
    }
    if (path === "/api/documents") return reply({ body: documentLists.at(-1) });
    if (path === "/api/jobs/job") {
      return reply(
        routes.job ?? { body: { status: "indexed", progress: 100, error: null, chunks: 4 } },
      );
    }
    throw new Error(`Unexpected request: ${path}`);
  });
  return { calls, documentLists };
}

function renderApp() {
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  render(
    <QueryClientProvider client={client}>
      <App />
    </QueryClientProvider>,
  );
}

function askFromHome(question = "Who sells anvils?") {
  fireEvent.change(screen.getByLabelText("Question"), { target: { value: question } });
  fireEvent.click(screen.getByRole("button", { name: "Ask" }));
}

describe("App", () => {
  it("shows the library and the provider", async () => {
    stubApi();
    renderApp();

    expect(await screen.findByText("ACME Corp · Form 10-K")).toBeTruthy();
    expect(screen.getByText("FY2025 · 12 chunks")).toBeTruthy();
    expect(await screen.findByText("LLM · fake")).toBeTruthy();
  });

  it("shows the empty library state without example questions", async () => {
    stubApi({ documents: [] });
    renderApp();

    expect(await screen.findByText(/No documents yet/)).toBeTruthy();
    expect(screen.queryByText("Try a question")).toBeNull();
  });

  it("asks a question and shows the cited answer", async () => {
    stubApi();
    renderApp();

    askFromHome();

    expect(await screen.findByRole("link", { name: "Source 1" })).toBeTruthy();
    expect(screen.getByRole("heading", { name: "Who sells anvils?" })).toBeTruthy();
  });

  it("rejects a question that is too short without calling the API", async () => {
    const { calls } = stubApi();
    renderApp();

    askFromHome("a ");

    expect(await screen.findByRole("alert")).toBeTruthy();
    expect(calls.some((call) => call.path === "/api/ask")).toBe(false);
  });

  it("sends the chosen company as a filter", async () => {
    const { calls } = stubApi();
    renderApp();
    await screen.findByRole("option", { name: "ACME Corp" });

    fireEvent.change(screen.getByLabelText("Search in"), { target: { value: "ACME" } });
    askFromHome();
    await screen.findByRole("link", { name: "Source 1" });

    const ask = calls.find((call) => call.path === "/api/ask");
    expect(JSON.parse(ask?.init?.body as string)).toMatchObject({
      filters: { tickers: ["ACME"] },
    });
  });

  it("shows the no-evidence card with the closest passages", async () => {
    stubApi({
      ask: {
        body: makeResponse({
          answer: "",
          insufficient_evidence: true,
          sources: [],
          retrieved: [makePassage(1)],
        }),
      },
    });
    renderApp();

    askFromHome();

    expect(await screen.findByText("Not enough evidence in your documents")).toBeTruthy();
    expect(screen.getByText("ACME 10-K · Item 1 — Business")).toBeTruthy();
  });

  it("returns to the form with the question kept when rephrasing", async () => {
    stubApi({
      ask: {
        body: makeResponse({ answer: "", insufficient_evidence: true, sources: [], retrieved: [] }),
      },
    });
    renderApp();
    askFromHome();

    fireEvent.click(await screen.findByRole("button", { name: "Rephrase the question" }));

    expect((screen.getByLabelText("Question") as HTMLTextAreaElement).value).toBe(
      "Who sells anvils?",
    );
  });

  it("shows the API's message on failure, and retry recovers", async () => {
    stubApi({
      ask: [{ status: 502, body: { detail: "The LLM provider timed out." } }, { body: makeResponse() }],
    });
    renderApp();
    askFromHome();

    expect(await screen.findByText("The LLM provider timed out.")).toBeTruthy();

    fireEvent.click(screen.getByRole("button", { name: "Try again" }));

    expect(await screen.findByRole("link", { name: "Source 1" })).toBeTruthy();
    expect(screen.queryByText("The LLM provider timed out.")).toBeNull();
  });

  it("clears the answer on New question", async () => {
    stubApi();
    renderApp();
    askFromHome();
    await screen.findByRole("link", { name: "Source 1" });

    fireEvent.click(screen.getByRole("button", { name: "New question" }));

    expect(screen.getByRole("heading", { name: "Ask about the indexed filings" })).toBeTruthy();
    expect(screen.queryByRole("link", { name: "Source 1" })).toBeNull();
  });
});

describe("upload dialog", () => {
  async function openDialog() {
    fireEvent.click(await screen.findByRole("button", { name: "Upload document" }));
    return screen.findByRole("dialog");
  }

  function chooseFile(name = "notes.txt") {
    const input = screen.getByLabelText("Choose files");
    fireEvent.change(input, { target: { files: [new File(["text"], name)] } });
  }

  it("is an accessible modal", async () => {
    stubApi();
    renderApp();

    const dialog = await openDialog();

    expect(dialog.getAttribute("aria-modal")).toBe("true");
    expect(dialog.contains(document.activeElement)).toBe(true);
  });

  it("needs a company before uploading", async () => {
    stubApi();
    renderApp();
    await openDialog();

    chooseFile();

    const upload = screen.getByRole("button", { name: "Upload 1 file" }) as HTMLButtonElement;
    expect(upload.disabled).toBe(true);
    expect(screen.getByText("Enter a company or ticker to upload.")).toBeTruthy();
  });

  it("uploads, polls the job and refreshes the library", async () => {
    const { calls, documentLists } = stubApi();
    renderApp();
    await openDialog();
    chooseFile();
    fireEvent.change(screen.getByLabelText("Company or ticker"), { target: { value: " ACME " } });
    documentLists.push([{ ...DOCUMENT, doc_id: "new", title: "notes.txt", ticker: null }]);

    fireEvent.click(screen.getByRole("button", { name: "Upload 1 file" }));

    expect(await screen.findByText("Indexed")).toBeTruthy();
    expect(screen.getByText(/4 passages/)).toBeTruthy();
    const post = calls.find((call) => call.init?.method === "POST");
    expect((post?.init?.body as FormData).get("company")).toBe("ACME");
    await waitFor(() => {
      expect(screen.getAllByText("notes.txt").length).toBeGreaterThan(1);
    });
  });

  it("shows a rejected file with the server's message", async () => {
    stubApi({ upload: { status: 415, body: { detail: "Unsupported file type." } } });
    renderApp();
    await openDialog();
    chooseFile("report.pdf");
    fireEvent.change(screen.getByLabelText("Company or ticker"), { target: { value: "ACME" } });

    fireEvent.click(screen.getByRole("button", { name: "Upload 1 file" }));

    expect(await screen.findByText("Unsupported file type.")).toBeTruthy();
    fireEvent.click(screen.getByRole("button", { name: "Remove" }));
    expect(screen.queryByText("report.pdf")).toBeNull();
  });

  it("shows a job that failed in the background", async () => {
    stubApi({
      job: { body: { status: "failed", progress: 0, error: "Too little text.", chunks: null } },
    });
    renderApp();
    await openDialog();
    chooseFile();
    fireEvent.change(screen.getByLabelText("Company or ticker"), { target: { value: "ACME" } });

    fireEvent.click(screen.getByRole("button", { name: "Upload 1 file" }));

    expect(await screen.findByText("Too little text.")).toBeTruthy();
  });

  it("drops unsent files on Cancel", async () => {
    stubApi();
    renderApp();
    await openDialog();
    chooseFile();

    fireEvent.click(screen.getByRole("button", { name: "Cancel" }));
    await openDialog();

    expect(screen.queryByText("notes.txt")).toBeNull();
  });
});
