  if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}
  if(m.method==="Runtime.exceptionThrown")problems.push("EXC "+m.params.exceptionDetails.text+" "+(m.params.exceptionDetails.exception?.description??"").slice(0,200));
  if(m.method==="Runtime.consoleAPICalled"&&["error","warning"].includes(m.params.type))problems.push(m.params.type+" "+m.params.args.map(a=>a.value??a.description).join(" ").slice(0,250));
};
const cdp=(method,params={})=>new Promise((res,rej)=>{const i=++id;pending.set(i,m=>m.error?rej(new Error(method+": "+m.error.message)):res(m.result));ws.send(JSON.stringify({id:i,method,params}))});
