  for(const type of ["mouseMoved","mousePressed","mouseReleased"])await cdp("Input.dispatchMouseEvent",{type,x:b.x,y:b.y,button:type==="mouseMoved"?"none":"left",clickCount:1});};
const click=(t,tag="button")=>clickEl(byText(tag,t));
const type=async(sel,t)=>{await clickEl(`document.querySelector(${JSON.stringify(sel)})`);await cdp("Input.insertText",{text:t})};
const key=async(k,code)=>{for(const ty of ["keyDown","keyUp"])await cdp("Input.dispatchKeyEvent",{type:ty,key:k,code,windowsVirtualKeyCode:code==="Escape"?27:13})};
const log=(...a)=>console.log(...a);
const hasSize=(w,h)=>cdp("Emulation.setDeviceMetricsOverride",{width:w,height:h,deviceScaleFactor:1,mobile:false});
try{
await cdp("Page.enable");await cdp("Runtime.enable");await cdp("Network.enable");await cdp("DOM.enable");await hasSize(1280,860);
await cdp("Page.navigate",{url:"http://localhost:5173/"});
await until(`document.body.innerText.includes('193 chunks')`);await shot("01-home");
log("1 home:",await js(`[...document.querySelectorAll('#scope option')].map(o=>o.textContent).join(' | ')`),"||",await js(`getComputedStyle(document.body).fontFamily.slice(0,20)`),"||",await js(`document.fonts.check('16px "IBM Plex Sans"')`));
await click("NVDA · 10-K");await until(`document.querySelector('[aria-label="Source 1"]')`,60000,"answer");await shot("02-answer");
log("2 answer:",await js(`document.querySelector('article').innerText.slice(0,260)`));
await clickEl(`document.querySelector('a[aria-label="Source 1"]')`);await sleep(600);
log("3 chip:",await js(`JSON.stringify({hl:document.getElementById('src-1').dataset.highlighted,focus:document.activeElement.id,hash:location.hash})`));await shot("03-highlight");
await click("Show retrieval details");await sleep(100);log("4 details:",await js(`document.querySelector('#src-1').innerText.match(/bm25.*/)?.[0]`));
await click("Show full passage");await sleep(100);await js(`document.querySelector('details').open=true`);await shot("04-details");
log("5 uncited:",await js(`document.querySelector('details').innerText.slice(0,200)`));
await click("New question");await until(`document.body.innerText.includes('Try a question')`);
await click("NOT IN LIBRARY");await until(`document.body.innerText.includes('Not enough evidence')`,60000,"no evidence");await shot("05-no-evidence");
log("6 none:",await js(`document.querySelector('article').innerText.slice(0,220)`));
await click("Rephrase the question");await sleep(100);log("7 rephrase:",await js(`document.querySelector('#question').value`));
await js(`document.querySelector('#question').focus()`);
await click("Upload document");await until(`document.querySelector('[role=dialog]')`);await sleep(300);
log("8 dialog:",await js(`JSON.stringify({modal:document.querySelector('[role=dialog]').getAttribute('aria-modal'),focusIn:document.querySelector('[role=dialog]').contains(document.activeElement)})`));
const {root}=await cdp("DOM.getDocument");const {nodeId}=await cdp("DOM.querySelector",{nodeId:root.nodeId,selector:"#file-input"});
await cdp("DOM.setFileInputFiles",{nodeId,files:[`${S}/zephyrine-memo.txt`]});await until(byText("button","Upload 1 file"));
log("9 disabled until company:",await js(`${byText("button","Upload 1 file")}.disabled`));await shot("06-upload-ready");
await type("#company","Zephyrine Kites Ltd");await click("Upload 1 file");
await until(`document.querySelector('[role=dialog]').innerText.includes('Indexed')`,30000,"indexed");await shot("07-upload-indexed");
log("10 queue:",await js(`document.querySelector('[role=dialog] ul').innerText.replace(/\\n/g,' / ')`));
await click("Done");await until(`!document.querySelector('[role=dialog]')`);await sleep(300);
log("11 focus back:",await js(`document.activeElement.textContent.trim().slice(0,30)`));
await until(`document.body.innerText.includes('zephyrine-memo.txt')`,8000,"library refresh");
log("12 library:",await js(`document.querySelector('aside').innerText.replace(/\\n/g,' / ').slice(-90)`),"||",await js(`[...document.querySelectorAll('#scope option')].map(o=>o.textContent).join(' | ')`));
await click("Upload document");await until(`document.querySelector('[role=dialog]')`);await key("Escape","Escape");await until(`!document.querySelector('[role=dialog]')`,3000,"escape closes");log("13 escape closes");
await js(`document.querySelector('#question').value`);
const sel=await js(`(()=>{const s=document.querySelector('#scope');const set=Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype,'value').set;set.call(s,'uploads');s.dispatchEvent(new Event('change',{bubbles:true}));return s.value})()`);
await clickEl(`document.querySelector('#question')`);await cdp("Input.dispatchKeyEvent",{type:"keyDown",key:"a",code:"KeyA",modifiers:4,commands:["selectAll"]});await cdp("Input.dispatchKeyEvent",{type:"keyUp",key:"a",code:"KeyA",modifiers:4});
await cdp("Input.insertText",{text:"How many kite makers work at the Larkmoor workshop?"});await click("Ask");
await until(`document.querySelector('[aria-label="Source 1"]')`,60000,"upload answer");await shot("08-upload-answer");
log("14 scoped:",sel,await js(`document.querySelector('article').innerText.replace(/\\n/g,' / ').slice(0,230)`));
await cdp("Network.setBlockedURLs",{urls:["*/api/ask"]});await click("Ask");
await until(`document.querySelector('[role=alert]')`,10000,"error card");await shot("09-error");log("15 error:",await js(`document.querySelector('[role=alert]').innerText.replace(/\\n/g,' / ')`));
await cdp("Network.setBlockedURLs",{urls:[]});await click("Try again");await until(`document.querySelector('[aria-label="Source 1"]')`,60000,"retry");log("16 retry ok");
await hasSize(390,844);await sleep(300);await shot("10-narrow");log("17 narrow overflow:",await js(`document.documentElement.scrollWidth`));
}catch(e){console.log("FAILED:",e.message);await shot("failure").catch(()=>{})}
console.log("console problems:",JSON.stringify([...new Set(problems)],null,1));
ws.close();chrome.kill();process.exit(0);
